parameters.jsCode:
// Recorremos los items que llegan del nodo anterior
for (const item of items) {

  // 1. OBTENER EL TEXTO CORRECTAMENTE
  // Primero intentamos la ruta específica de Gemini que mostraste (content.parts[0].text)
  // Si no existe, probamos fallbacks comunes.
  let textoRespuesta = null;

  if (item.json.content && item.json.content.parts && item.json.content.parts[0]) {
      textoRespuesta = item.json.content.parts[0].text;
  } else {
      // Fallbacks para otros nodos (OpenAI, Anthropic, o si la estructura varía)
      textoRespuesta = item.json.text || item.json.output || (item.json.message && item.json.message.content);
  }

  try {
    if (!textoRespuesta) throw new Error("No se encontró texto en content.parts[0].text ni en variables estándar.");

    // 2. EXTRAER LIMPIAMENTE EL BLOQUE JSON
    // Busca desde la primera llave { hasta la última } ignorando el resto
    const match = textoRespuesta.match(/\{[\s\S]*\}/);

    if (!match) throw new Error("El texto encontrado no contiene llaves JSON {}");

    const jsonString = match[0];

    // 3. CONVERTIR A OBJETO
    const datos = JSON.parse(jsonString);

    // 4. ASIGNAR VARIABLES UNA A UNA
    item.json.fecha = datos.fecha;
    item.json.tipo_documento = datos.tipo_documento;
    item.json.numero_documento = datos.numero_documento;
    item.json.proveedor = datos.proveedor;
    item.json.rut_proveedor = datos.rut_proveedor;
    item.json.detalle_gasto = datos.detalle_gasto;
    item.json.actividad = datos.actividad;
    item.json.monto = datos.monto;

    // Campo fijo según instrucciones
    item.json.link_documento = "falta por rellenar";

  } catch (error) {
    // Si falla, dejamos un aviso simple en el item
    item.json.error = "Error al parsear: " + error.message;
  }
}

return items;

